ax.set_xlim(b[0],b[2]);ax.set_ylim(b[1],b[3]);ax.set_aspect(1/math.cos(math.radians(21.021)));ax.set_xlabel('Kinh độ Đông');ax.set_ylabel('Vĩ độ Bắc');ax.set_title('Vùng thử 5,2 km² quanh Láng · một đường mới và ba nhánh\nHình học giả định, chưa đánh giá khả thi xây dựng',fontsize=12);ax.ticklabel_format(useOffset=False,style='plain');ax.tick_params(axis='x',rotation=25);ax.grid(alpha=.15);ax.annotate('Bắc ↑',(.96,.96),xycoords='axes fraction',ha='right',va='top');ax.legend(handles=[Line2D([0],[0],color='#9aabb4',lw=1,label='Đường hiện trạng được giữ'),Line2D([0],[0],color='#7950a5',lw=3,label='L1: đường mới'),Line2D([0],[0],color='#cf701c',lw=2,label='L2–L4: nhánh')],loc='lower right',fontsize=8)
