def f(v,n=1):return f'{v:,.{n}f}'.replace(',',' ').replace('.',',')
def pct(v):return ('+' if v>=0 else '')+f(v)+'%'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
main=table(['Phương án','Hoàn thành / 45.000','Tổng chờ (xe·giờ)','Chờ / chuyến đặt (giây)','Spillback (đoạn·phút)','Nút đèn mới giả định'],[[labels[i],f(s['metrics']['completed'],0),f(s['metrics']['total_wait_veh_h']),f(s['averageWaitSecondsPerRequestedTrip']),f(s['metrics']['spillback_link_min']),s['additionalSignalNodes']] for i,s in enumerate(sc)])
diagnostics=table(['Phương án','Gộp về cạnh đầu vào (đoạn·phút)','PCU·phút trên đoạn bị chặn','km đường·phút bị chặn'],[[labels[i],f(s['spillbackDiagnostics']['normalizedLinkMinutes']),f(s['spillbackDiagnostics']['blockedPcuMinutes']),f(s['spillbackDiagnostics']['blockedRoadKmMinutes'])] for i,s in enumerate(sc)])
usage=table(['Tuyến','Loại','Dài (m)','Làn / chiều','Chuyến thực sự đi vào'],[[l['id'],'Đường mới' if l['kind']=='road' else 'Nhánh',f(sum(math.hypot((q['ll'][0]-p['ll'][0])*111320*math.cos(math.radians(21.021)),(q['ll'][1]-p['ll'][1])*111320) for p,q in zip(l['points'],l['points'][1:])),0),l['lanes'],f(sc[2]['usage'][l['id']]['entered'],0)] for l in r['design']['lines']])
c=r['comparisons']['full_vs_baseline'];m=r['comparisons']['branches_vs_road_only'];wait_delta=c['total_wait_veh_h']['delta'];spill_delta=c['spillback_link_min']['delta'];wait_seconds=sc[2]['averageWaitSecondsPerRequestedTrip']-sc[0]['averageWaitSecondsPerRequestedTrip'];existing_delta=sc[2]['retainedExistingMeters']-sc[0]['retainedExistingMeters'];diag_pct=100*(sc[2]['spillbackDiagnostics']['blockedRoadKmMinutes']/sc[0]['spillbackDiagnostics']['blockedRoadKmMinutes']-1)
body=f'''<p class="eyebrow">CA THỬ NGÀY 30/10/2026 · MÔ PHỎNG GIẢ ĐỊNH, CHƯA HIỆU CHỈNH THỰC ĐỊA</p><h1>45.000 chuyến trong 5,2 km²</h1><p class="lead">Giữ cùng nhu cầu, thêm một đường và ba nhánh: trong ca này, tổng chờ tăng {f(c['total_wait_veh_h']['percent'])}%, spillback tăng {f(c['spillback_link_min']['percent'])}%.</p><p><a class="button" href="../../trial-area-45000.html">Mở bản thử riêng</a> <a href="../../index.html">Giả lập chính</a></p><p>Bản thử dùng thiết kế và đầu vào bên dưới, lưu riêng trong trình duyệt để không thay thiết kế của bản chính. Bấm So sánh hai phương án để chạy lại.</p>
<h2>Kết quả sau 24 giờ phát sinh + 1 giờ xả</h2>{main}<p>Phương án đầy đủ tăng <strong>{f(wait_delta)} xe·giờ</strong>, tương đương <strong>{f(wait_seconds)} giây chờ trên mỗi chuyến đặt</strong>; spillback tăng <strong>{f(spill_delta)} đoạn·phút</strong>. Cả ba hoàn thành đủ 45.000 chuyến và không còn xe chờ cuối kỳ. Throughput trung bình trong cửa sổ 25 giờ đều là 1.800 xe/giờ; điều này không chứng minh năng lực cực đại của ba mạng bằng nhau.</p><p>Ca trung gian chỉ thêm đường có tổng chờ {f(sc[1]['metrics']['total_wait_veh_h'])} xe·giờ. Ba nhánh làm tăng thêm {f(m['total_wait_veh_h']['delta'])} xe·giờ ({pct(m['total_wait_veh_h']['percent'])}) và {f(m['spillback_link_min']['delta'])} đoạn·phút ({pct(m['spillback_link_min']['percent'])}) so với ca chỉ thêm đường.</p>
<img src="time-series.png" alt="Bốn đồ thị so sánh chờ, spillback, xe đang chờ và lưu lượng hoàn thành theo thời gian"><p class="small">Đồ thị và đỉnh hàng chờ lấy mẫu mỗi 60 giây. Spillback được cộng ở từng bước 2 giây.</p>
<h2>Vùng và thiết kế đã cố định trước khi chạy</h2><p>Khung [105.802, 21.012, 105.827, 21.030], diện tích {f(r['scope']['areaStats']['km2'],2)} km² quanh Láng. Bộ lọc Ẩn đường ngõ giữ các lớp motorway/trunk/primary/secondary/tertiary và đường nối tương ứng; hình học lấy từ OSM. L1 dùng nguyên tuyến mẫu có sẵn, không chọn lại sau kết quả 45.000 chuyến. Ba nhánh đặt ở 25%, 50%, 75% chiều dài L1, nối đến ba nhóm đường hiện trạng khác nhau theo khoảng cách; không tối ưu theo kết quả.</p><img src="design-map.png" alt="Bản đồ vùng 5,2 km² với L1 màu tím và ba nhánh L2 L3 L4 màu cam">{usage}<p>Số chuyến theo tuyến có thể chồng nhau. Tất cả các lượt chọn tuyến trên đây đã thực sự đi vào và hoàn thành trong ca này. L1 có {f(sc[1]['usage']['L1']['entered'],0)} chuyến dùng khi chưa có ba nhánh, và {f(sc[2]['usage']['L1']['entered'],0)} khi có đủ nhánh.</p>
<h2>Giữ cùng nhu cầu và kiểm tra bảo toàn</h2><p>Tạo một lần tập {f(r['tripCount'],0)} chuyến từ hiện trạng trong khung; dùng chính xác cùng các đối tượng chuyến cho cả ba động cơ. Cùng OD, giờ đi, loại xe, seed 42, hai cao điểm sáng/chiều. Thực tế mẫu có {f(audit['motorcycles'],0)} xe máy và {f(audit['cars'],0)} ô tô; xác suất xe máy đặt là 80%. Mã nhu cầu <code>{r['demandFingerprint']}</code>. Không có nhu cầu phát sinh thêm.</p><p>Các cửa vào/ra và điểm nội vùng được chọn chỉ từ hiện trạng, không đổi riêng cho phương án mới. Nhu cầu 45.000 chuyến áp dụng riêng cho khung này, chưa được suy ra từ số đếm giao thông thực địa. Hàng đợi ngoài mạng và xe chưa xong đều được tính. Sai số bảo toàn xe của cả ba ca bằng 0; dung tích lớn nhất ghi nhận không vượt giới hạn. Chiều dài đường hiện trạng giữ lại giữa ca đầy đủ và hiện trạng lệch {f(existing_delta,6)} m.</p><p><a href="trips.csv.gz">Đủ 45.000 chuyến CSV nén</a> · <a href="demand_audit.json">Đối chiếu nhu cầu và SHA-256</a></p>
<h2>Kiểm tra spillback khi số đoạn thay đổi</h2><p>Đường mới chia một số đường cũ thành nhiều cạnh; ba ca có {', '.join(str(s['links']) for s in sc)} đoạn có hướng. Vì vậy đã chạy lại nguyên đầu vào và kiểm tra thêm spillback sau khi gộp các đoạn chia về cùng cạnh có hướng của mạng đầu vào trước khi thêm đường, mỗi cạnh đầu vào chỉ đếm một lần trong một bước. Các số chờ và spillback gốc khớp chính xác lần chạy đầu; không thay hình học, nhu cầu hay tham số.</p>{diagnostics}<p>Trong ca này, gộp về cạnh đầu vào cho cùng kết quả spillback với chỉ số gốc; phần km đường·phút bị chặn tăng {f(diag_pct)}%. Spillback được ghi nhận trên các đường hiện trạng, không nằm trên chính tuyến và nhánh mới. Một đoạn bị chặn 10 phút đóng góp 10 đoạn·phút; chỉ số này không phải số phút một tài xế phải chờ.</p>
<h2>Diễn giải có giới hạn</h2><p>Phương án đầy đủ có thêm {sc[2]['additionalSignalNodes']} nút tín hiệu giả định trong mạng tính toán, so với {sc[1]['additionalSignalNodes']} khi chỉ thêm đường. Đường mới và nhánh đồng thời đổi tuyến đi, chuyển hướng, xung đột và số điểm điều khiển; ca thử chưa tách riêng đóng góp của từng cơ chế. Đường mới được sử dụng nhưng tổng chờ vẫn tăng trong chính mô hình này.</p><p>Định tuyến cố định theo chi phí chạy tự do và chờ đèn trung bình, không chuyển tuyến theo ùn tắc khi đang chạy. Đèn mới mặc định chu kỳ 90 giây; tốc độ, năng lực, PCU và điểm đi–đến là giả định. Chỉ một hạt giống, một thiết kế; không có khoảng tin cậy hay kết luận quy hoạch. Các đường thẳng vẽ thêm có thể cắt qua công trình hoặc không gian không thể xây dựng. Chưa hiệu chỉnh và kiểm định bằng giao thông thực địa.</p>
<h2>Tái lập và nguồn</h2><p><a href="config.json">Cấu hình</a> · <a href="design.json">Thiết kế</a> · <a href="protocol.json">Quy tắc cố định trước khi chạy</a> · <a href="result.json">Kết quả đầy đủ</a> · <a href="summary.csv">Bảng CSV</a> · <a href="networks.geojson">Ba mạng GeoJSON</a> · <a href="first_run_summary.json">Số liệu lần chạy đầu</a> · <a href="browser_check.json">Đối chiếu giao diện</a></p><p><code>node scripts/run_area_45000.cjs</code> chạy lại ba ca từ thiết kế đã đóng băng; <code>node scripts/export_area_45000.cjs</code> xuất mạng và nhu cầu. Mã mô hình tại commit nền {r['protocol']['baselineCommit'][:7]}.</p><p><a href="../../region-report.html">Phương pháp và nguồn vùng Vành đai 3</a> · <a href="../../data/rr3_provenance.json">Provenance dữ liệu</a>. © OpenStreetMap contributors / Geofabrik, ODbL 1.0; WorldPop 2020 / University of Southampton, CC BY 4.0. Mã nguồn MIT.</p>'''
